72	    /**
73	     * Syntactic check for an email address: a non-empty local part, a single {@code @}, and a
74	     * domain containing at least one dot, with no whitespace in any part.
75	     */
76	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
