125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
128	        Collection<Owner> owners;
129	        if (lastName != null) {
130	            owners = this.clinicService.findOwnerByLastName(lastName);
131	        } else {
132	            owners = this.clinicService.findAllOwners();
133	        }
134	        if (owners.isEmpty()) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
138	    }
