150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
153	        validateRequiredFields(ownerFieldsDto);
154	        LocalDate registrationDate = toBusinessDay(
155	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now());
156	        rejectDailyLimitReached(registrationDate);
157	        HttpHeaders headers = new HttpHeaders();
158	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
159	        String address = normalizeAddress(ownerFieldsDto.getAddress());
160	        owner.setAddress(address);
161	        rejectCityAtCapacity(owner.getCity());
162	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
163	            assignHousehold(owner, ownerFieldsDto.getLastName(), address);
164	        } else {
165	            rejectDuplicateHousehold(ownerFieldsDto.getLastName(), address);
166	        }
167	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
168	        rejectDuplicateTelephone(telephone);
169	        owner.setTelephone(telephone);
170	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
171	        owner.setRegistrationDate(registrationDate);
172	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
173	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
174	        this.clinicService.saveOwner(owner);
175	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
176	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
177	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
178	        headers.setLocation(UriComponentsBuilder.newInstance()
179	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
180	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
181	    }
