193	        currentOwner.setLastName(ownerFieldsDto.getLastName());
194	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
195	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
196	        this.clinicService.saveOwner(currentOwner);
