277	    /**
278	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
279	     * already rejects {@code null} values and some formats, but a whitespace-only value can still
280	     * satisfy a {@code @Size(min = 1)} constraint; this guard catches those remaining cases.
281	     *
282	     * @param ownerFieldsDto the submitted owner fields
283	     * @throws InvalidOwnerFieldsException if any required field is missing or blank, carrying the
284	     *                                     name of every offending field
285	     */
286	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
287	        List<String> missingFields = new ArrayList<>();
288	        if (isBlank(ownerFieldsDto.getFirstName())) {
289	            missingFields.add("firstName");
290	        }
291	        if (isBlank(ownerFieldsDto.getLastName())) {
292	            missingFields.add("lastName");
293	        }
294	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
295	            missingFields.add("address");
296	        }
297	        if (isBlank(ownerFieldsDto.getCity())) {
298	            missingFields.add("city");
299	        }
300	        if (isBlank(ownerFieldsDto.getTelephone())) {
301	            missingFields.add("telephone");
302	        }
303	        if (!missingFields.isEmpty()) {
304	            throw new InvalidOwnerFieldsException(missingFields);
305	        }
306	    }
307	
308	    private boolean isBlank(String value) {
309	        return value == null || value.isBlank();
310	    }
311	
312	    /**
313	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes and brackets
314	     * are stripped. When the value carries a leading {@code '+'} the country code it supplies is kept;
315	     * otherwise the number is treated as a national Australian number, so a single leading {@code '0'}
316	     * is dropped and the {@code '+61'} country code is prepended. The result must be a {@code '+'}
317	     * followed by 8 to 15 digits. This E.164 string is what gets stored and returned.
318	     *
319	     * @param telephone the raw telephone value submitted by the client
320	     * @return the telephone in E.164 form, e.g. {@code +61412345678}
321	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number, yielding a
322	     *                                     400 response
323	     */
324	    private String normalizeTelephone(String telephone) {
325	        String e164 = toE164(telephone);
326	        if (e164 == null) {
327	            throw new InvalidOwnerFieldsException(List.of("telephone"));
328	        }
329	        return e164;
330	    }
331	
332	    /**
333	     * Converts a raw telephone value to E.164 form, or returns {@code null} if it cannot form a valid
334	     * E.164 number. Spaces, dashes and brackets are removed; a leading {@code '+'} keeps the supplied
335	     * country code, while a bare national number has a single leading {@code '0'} dropped and the
336	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits.
337	     *
338	     * @param telephone the raw telephone value, possibly {@code null}
339	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
340	     */
341	    private String toE164(String telephone) {
342	        if (telephone == null) {
343	            return null;
344	        }
345	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
346	        boolean hasPlus = cleaned.startsWith("+");
347	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
348	        String nationalSignificant = hasPlus
349	            ? digits
350	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
351	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
352	            return null;
353	        }
354	        return "+" + nationalSignificant;
355	    }
356	
357	    /**
358	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
359	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
360	     * returned value is that address lower-cased.
361	     *
362	     * @param email the raw email value submitted by the client, or {@code null} if omitted
363	     * @return the lower-cased email, or {@code null} if none was supplied
364	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
365	     *                                     yielding a 400 response
366	     */
367	    private String normalizeEmail(String email) {
368	        if (email == null) {
369	            return null;
370	        }
371	        if (!EMAIL_PATTERN.matcher(email).matches()) {
372	            throw new InvalidOwnerFieldsException(List.of("email"));
373	        }
374	        return email.toLowerCase(Locale.ROOT);
375	    }
