377	    /**
378	     * Counts the existing owners that, before this create, already share the given first name and
379	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
380	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
381	     * been saved yet, so it is never included in the count.
382	     *
383	     * @param firstName the first name of the owner being created
384	     * @param lastName  the last name of the owner being created
385	     * @return the number of existing owners sharing both names
386	     */
387	    private int countNamesakes(String firstName, String lastName) {
388	        String normalizedFirstName = normalizeForComparison(firstName);
389	        String normalizedLastName = normalizeForComparison(lastName);
390	        return (int) this.clinicService.findAllOwners().stream()
391	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
392	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
393	            .count();
394	    }
395	
396	    /**
397	     * Builds the owner's {@code customerCode}, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3}
398	     * is the upper-cased first three letters of the city, {@code LAST3} the upper-cased first three
399	     * letters of the last name, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one
400	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
401	     *
402	     * @param city     the owner's city
403	     * @param lastName the owner's last name
404	     * @return the formatted customer code
405	     */
406	    private String generateCustomerCode(String city, String lastName) {
407	        String city3 = first3Letters(city);
408	        String last3 = first3Letters(lastName);
409	        int sequence = countOwnersInCity(city) + 1;
410	        return String.format("%s-%s-%04d", city3, last3, sequence);
411	    }
412	
413	    /**
414	     * Returns the upper-cased first three letters of the given value, with any non-letter characters
415	     * removed first, used to build the city and last-name segments of a {@code customerCode}.
416	     *
417	     * @param value the value to abbreviate
418	     * @return the upper-cased first three letters, or fewer if the value has fewer letters
419	     */
420	    private String first3Letters(String value) {
421	        String letters = value.replaceAll("[^\\p{L}]", "");
422	        return letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
423	    }
424	
425	    /**
426	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
427	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
428	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
429	     * has not been saved yet, so it is never included in the count.
430	     *
431	     * @param city the city of the owner being created
432	     * @return the number of existing owners in that city
433	     */
434	    private int countOwnersInCity(String city) {
435	        String normalizedCity = normalizeForComparison(city);
436	        return (int) this.clinicService.findAllOwners().stream()
437	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
438	            .count();
439	    }
440	
441	    /**
442	     * Rejects creation of an owner whose city already contains the maximum number of owners
443	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
444	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
445	     *
446	     * @param city the city of the owner being created
447	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
448	     *                                      owners, yielding a 409 Conflict response
449	     */
450	    private void rejectCityAtCapacity(String city) {
451	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
452	            throw new OwnerCityAtCapacityException(city);
453	        }
454	    }
455	
456	    /**
457	     * Rejects creation of an owner once the given business day has already reached its daily quota
458	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
459	     * being that day — the adjusted business day the owner being created will carry — so the quota
460	     * applies per business day. The owner being created has not been saved yet, so it is never
461	     * included in the count.
462	     *
463	     * @param registrationDate the adjusted business-day registration date of the owner being created
464	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
465	     *                                         carry that registration date, yielding a
466	     *                                         429 Too Many Requests response
467	     */
468	    private void rejectDailyLimitReached(LocalDate registrationDate) {
469	        long createdThatDay = this.clinicService.findAllOwners().stream()
470	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
471	            .count();
472	        if (createdThatDay >= DAILY_OWNER_LIMIT) {
473	            throw new DailyOwnerLimitReachedException(registrationDate);
474	        }
475	    }
476	
477	    /**
478	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
479	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
480	     * applies to the effective registration date whether it was supplied in the request or defaulted
481	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
482	     * feeds every value derived from it (such as the membership number's year segment and the daily
483	     * create-limit's per-day bucket).
484	     *
485	     * @param date the effective registration date, supplied or defaulted
486	     * @return the same date when it is a weekday, otherwise the next Monday
487	     */
488	    private LocalDate toBusinessDay(LocalDate date) {
489	        LocalDate adjusted = date;
490	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
491	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
492	            adjusted = adjusted.plusDays(1);
493	        }
494	        return adjusted;
495	    }
496	
497	    /**
498	     * Rejects creation of an owner whose E.164 telephone is already used by any other owner. Stored
499	     * telephones are converted to E.164 here as well so the comparison is independent of the format
500	     * each owner was originally saved with; a stored value that cannot form a valid E.164 number is
501	     * ignored rather than matched.
502	     *
503	     * @param telephone the E.164 telephone of the owner being created
504	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone,
505	     *                                          yielding a 409 Conflict response
506	     */
507	    private void rejectDuplicateTelephone(String telephone) {
508	        boolean inUse = this.clinicService.findAllOwners().stream()
509	            .map(Owner::getTelephone)
510	            .map(this::toE164)
511	            .anyMatch(telephone::equals);
512	        if (inUse) {
513	            throw new DuplicateOwnerTelephoneException(telephone);
514	        }
515	    }
516	
517	    /**
518	     * Rejects creation of an owner whose last name and address both match an existing owner's,
519	     * which marks them as belonging to the same household. Both the last name and the address are
520	     * compared case-insensitively with surrounding and internal whitespace collapsed, so values
521	     * that differ only in letter case or spacing are still treated as a match.
522	     *
523	     * @param lastName the last name of the owner being created
524	     * @param address  the address of the owner being created
525	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
526	     *                                          address, yielding a 409 Conflict response
527	     */
528	    private void rejectDuplicateHousehold(String lastName, String address) {
529	        if (!findHouseholdMembers(lastName, address).isEmpty()) {
530	            throw new DuplicateOwnerHouseholdException(lastName, address);
531	        }
532	    }
533	
534	    /**
535	     * Finds every existing owner belonging to the household identified by the given last name and
536	     * address — that is, the owners the duplicate-household rule rejects and the {@code sharesHousehold}
537	     * opt-in joins. Both the last name and the address are compared case-insensitively with surrounding
538	     * and internal whitespace collapsed, so values that differ only in letter case or spacing still
539	     * match. This single definition of household membership is shared by {@link #rejectDuplicateHousehold}
540	     * and {@link #assignHousehold}.
541	     *
542	     * @param lastName the last name of the owner being created
543	     * @param address  the address of the owner being created
544	     * @return the existing owners in that household, or an empty list if there are none
545	     */
546	    private List<Owner> findHouseholdMembers(String lastName, String address) {
547	        String normalizedLastName = normalizeForComparison(lastName);
548	        String normalizedAddress = normalizeAddress(address);
549	        return this.clinicService.findAllOwners().stream()
550	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
551	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
552	            .toList();
553	    }
554	
555	    /**
556	     * Enrolls a newly created owner into the household of any existing owner that shares its last
557	     * name and address, so an owner that opts in via {@code sharesHousehold} is accepted instead of
558	     * rejected as a duplicate. Last name and address are compared case-insensitively with collapsed
559	     * whitespace. When at least one such owner already exists, every member of the household — the
560	     * existing owners and the new one — is assigned the same stable {@code householdId}; if a member
561	     * already carries one it is reused, otherwise a new identifier derived from the shared last name
562	     * and address is created and back-filled onto the existing members. When no owner yet lives at
563	     * that address under the same last name no identifier is assigned and the owner is created alone.
564	     *
565	     * @param newOwner the owner being created, whose {@code householdId} will be set on a match
566	     * @param lastName the last name of the owner being created
567	     * @param address  the address of the owner being created
568	     * @return the assigned {@code householdId}, or {@code null} if there was no household to join
569	     */
570	    private String assignHousehold(Owner newOwner, String lastName, String address) {
571	        List<Owner> members = findHouseholdMembers(lastName, address);
572	        if (members.isEmpty()) {
573	            return null;
574	        }
575	        String householdId = members.stream()
576	            .map(Owner::getHouseholdId)
577	            .filter(existing -> existing != null && !existing.isBlank())
578	            .findFirst()
579	            .orElseGet(() -> generateHouseholdId(normalizeForComparison(lastName), normalizeAddress(address)));
580	        for (Owner member : members) {
581	            if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
582	                member.setHouseholdId(householdId);
583	                this.clinicService.saveOwner(member);
584	            }
585	        }
586	        newOwner.setHouseholdId(householdId);
587	        return householdId;
588	    }
589	
590	    /**
591	     * Derives a stable household identifier, formatted {@code 'HH-<HEX12>'}, where {@code HEX12} is
592	     * the first twelve upper-cased hex characters of the SHA-256 digest of the normalized last name
593	     * and address joined by a {@code '|'}. The same last name and address therefore always yield the
594	     * same identifier, so members of one household share a single value.
595	     *
596	     * @param normalizedLastName the household's last name, already normalized for comparison
597	     * @param normalizedAddress  the household's address, already normalized for comparison
598	     * @return the derived household identifier
599	     */
600	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
601	        try {
602	            byte[] digest = MessageDigest.getInstance("SHA-256")
603	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
604	            StringBuilder hex = new StringBuilder(digest.length * 2);
605	            for (byte b : digest) {
606	                hex.append(String.format("%02x", b));
607	            }
608	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
609	        } catch (NoSuchAlgorithmException e) {
610	            throw new IllegalStateException("SHA-256 algorithm not available", e);
611	        }
612	    }
613	
614	    /**
615	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
616	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
617	     * the result is lower-cased.
618	     *
619	     * @param value the value to normalize, possibly {@code null}
620	     * @return the normalized value, or an empty string if {@code value} is {@code null}
621	     */
622	    private String normalizeForComparison(String value) {
623	        if (value == null) {
624	            return "";
625	        }
626	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
627	    }
628	
629	    /**
630	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
631	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
632	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
633	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
634	     * This normalized value is what gets stored and returned, and it is the form every address
635	     * comparison (household duplicate detection and the shared household id) uses.
636	     *
637	     * @param address the raw address value submitted by the client, possibly {@code null}
638	     * @return the normalized address, or an empty string if {@code address} is {@code null}
639	     */
640	    private String normalizeAddress(String address) {
641	        if (address == null) {
642	            return "";
643	        }
644	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
645	        if (collapsed.isEmpty()) {
646	            return collapsed;
647	        }
648	        String[] tokens = collapsed.split(" ");
649	        StringBuilder normalized = new StringBuilder(collapsed.length());
650	        for (int i = 0; i < tokens.length; i++) {
651	            if (i > 0) {
652	                normalized.append(' ');
653	            }
654	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
655	        }
656	        return normalized.toString();
657	    }
658	}
